<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Download, Film, LoaderCircle, Plus, RefreshCw, Save, ShieldCheck, Volume2, VolumeX } from '@lucide/vue'
import { createVideoProject, downloadVideoOutput, getVideoOutputBlob, getVideoProject, listVideoProjects, renderVideoProject, reviseVideoScript } from '../api'

const defaults=()=>[
 {title:'边缘智能是什么',narration:'边缘智能把模型推理带到资源受限设备，在本地完成低延迟决策。',bullets:['资源受限设备','低延迟与离线能力'],duration_ms:4000},
 {title:'从训练到部署',narration:'完成训练和验证后，通过量化压缩模型，再部署到嵌入式设备。',bullets:['训练与验证','量化','设备部署'],duration_ms:4500},
]
const items=ref([]),current=ref(null),runtime=ref({}),loading=ref(true),busy=ref(false),error=ref(''),title=ref('嵌入式边缘智能技能微课'),scenes=ref(defaults())
const latest=computed(()=>current.value?.tasks?.find(x=>x.status==='completed'&&x.output)||null)
const videoUrl=ref('')
function message(e,f){const d=e?.response?.data?.detail;return d?.message||e?.message||f}
async function load(){loading.value=true;error.value='';try{const data=await listVideoProjects();items.value=data.items;runtime.value=data.runtime;if(items.value.length)await open(items.value[0].id)}catch(e){error.value=message(e,'视频项目加载失败')}finally{loading.value=false}}
async function open(id){current.value=await getVideoProject(id);title.value=current.value.title;scenes.value=current.value.script.scenes.map(({order,...x})=>({...x}));items.value=items.value.map(x=>x.id===id?current.value:x)}
function addScene(){if(scenes.value.length<12)scenes.value.push({title:'新分镜',narration:'填写本段讲稿。',bullets:['关键要点'],duration_ms:4000})}
function removeScene(index){if(scenes.value.length>1)scenes.value.splice(index,1)}
async function create(){busy.value=true;error.value='';try{const row=await createVideoProject({title:title.value,scenes:scenes.value});items.value=[row,...items.value];current.value=row}catch(e){error.value=message(e,'创建失败')}finally{busy.value=false}}
async function save(){if(!current.value)return;busy.value=true;error.value='';try{current.value=await reviseVideoScript(current.value.id,{expected_version:current.value.lock_version,scenes:scenes.value});items.value=items.value.map(x=>x.id===current.value.id?current.value:x)}catch(e){error.value=message(e,'脚本保存失败')}finally{busy.value=false}}
async function render(){if(!current.value)return;busy.value=true;error.value='';try{const task=await renderVideoProject(current.value.id,{idempotency_key:`ui-${current.value.id}-${current.value.script.id}-${Date.now()}`});current.value=await getVideoProject(current.value.id);if(task.status!=='completed')error.value=task.error_message||'渲染未完成'}catch(e){error.value=message(e,'离线渲染失败')}finally{busy.value=false}}
function download(name){if(latest.value)downloadVideoOutput(latest.value.output.id,name)}
watch(()=>latest.value?.output?.id,async id=>{if(videoUrl.value)URL.revokeObjectURL(videoUrl.value);videoUrl.value='';if(id)try{videoUrl.value=URL.createObjectURL(await getVideoOutputBlob(id,'course-video.mp4'))}catch(e){error.value=message(e,'视频预览加载失败')}},{immediate:true})
onMounted(load)
onBeforeUnmount(()=>{if(videoUrl.value)URL.revokeObjectURL(videoUrl.value)})
</script>
<template>
<main class="studio" data-testid="video-studio">
 <header><div><p class="eyebrow">OFFLINE VIDEO PIPELINE</p><h1>技能微课视频制作</h1><p>分镜、字幕、画面与音轨在本机生成；无网络、无 API Key、无 Docker。</p></div><div class="runtime" :class="runtime.available?'ok':'bad'"><ShieldCheck :size="18"/><span>{{runtime.available?'离线运行时就绪':'运行时不可用'}}</span><small>FFmpeg {{runtime.ffmpeg_version||'未检测'}} · {{runtime.audio_available?runtime.sapi_voice:'文本与字幕降级'}}</small></div></header>
 <p v-if="error" class="notice err">{{error}}</p><p v-if="loading" class="notice">正在恢复视频项目...</p>
 <template v-else>
  <section class="toolbar"><select v-if="items.length" :value="current?.id" aria-label="选择视频项目" @change="open($event.target.value)"><option v-for="x in items" :key="x.id" :value="x.id">{{x.title}} · script v{{x.script.version_number}}</option></select><button :disabled="busy" @click="current=null;scenes=defaults();title='嵌入式边缘智能技能微课'"><Plus :size="15"/>新项目</button><button :disabled="busy" @click="load"><RefreshCw :size="15"/>刷新</button></section>
  <div class="layout">
   <section class="editor"><div class="section-head"><div><strong>分镜脚本</strong><small v-if="current">不可变版本 {{current.script.version_number}} · lock {{current.lock_version}}</small></div><input v-model="title" aria-label="视频标题" maxlength="256"/></div>
    <article v-for="(scene,index) in scenes" :key="index" data-testid="video-scene"><div class="scene-no">{{index+1}}</div><div class="fields"><input v-model="scene.title" :aria-label="`分镜${index+1}标题`" maxlength="80"/><textarea v-model="scene.narration" :aria-label="`分镜${index+1}讲稿`" maxlength="500"/><input :value="scene.bullets.join('；')" :aria-label="`分镜${index+1}要点`" @input="scene.bullets=$event.target.value.split('；').filter(Boolean).slice(0,5)"/><label>时长 <input v-model.number="scene.duration_ms" type="number" min="1500" max="15000" step="500"/> ms</label></div><button class="remove" title="删除分镜" @click="removeScene(index)">×</button></article>
    <div class="actions"><button :disabled="scenes.length>=12" @click="addScene"><Plus :size="14"/>添加分镜</button><button v-if="!current" class="primary" :disabled="busy||!runtime.available" @click="create"><Save :size="14"/>创建项目</button><button v-else :disabled="busy" @click="save"><Save :size="14"/>保存新脚本版本</button><button v-if="current" class="primary" :disabled="busy||!runtime.available" @click="render"><LoaderCircle v-if="busy" :size="14" class="spin"/><Film v-else :size="14"/>生成 MP4</button></div>
   </section>
   <aside><div class="truth"><Volume2 v-if="latest?.audio_status==='sapi_zh_cn'" :size="17"/><VolumeX v-else :size="17"/><div><strong>{{latest?.audio_status==='sapi_zh_cn'?'本地中文配音':'字幕与讲稿模式'}}</strong><small>{{latest?.output?.quality_report?.truth_boundary||'系统将按实际音轨结果标记，不伪报配音。'}}</small></div></div>
    <div v-if="latest" class="preview"><video :key="latest.output.id" :src="videoUrl" controls data-testid="rendered-video"/><dl><dt>输出版本</dt><dd>v{{latest.output.version_number}}</dd><dt>质量</dt><dd>{{latest.output.quality_report.passed?'PASS':'FAIL'}} · {{latest.output.quality_report.resolution}}</dd><dt>时长</dt><dd>{{(latest.output.duration_ms/1000).toFixed(1)}} 秒</dd><dt>音轨</dt><dd>{{latest.audio_status}}</dd><dt>MP4 SHA-256</dt><dd class="hash">{{latest.output.mp4_sha256}}</dd></dl><div class="downloads"><button @click="download('course-video.mp4')"><Download :size="13"/>MP4</button><button @click="download('subtitles.srt')"><Download :size="13"/>SRT</button><button @click="download('subtitles.vtt')"><Download :size="13"/>VTT</button><button @click="download('transcript.json')"><Download :size="13"/>讲稿</button></div></div>
    <div v-else class="empty"><Film :size="28"/><strong>尚无渲染成品</strong><span>创建项目后生成首个离线 MP4。</span></div>
    <div v-if="current?.tasks?.length" class="history"><strong>任务历史</strong><div v-for="task in current.tasks" :key="task.id"><span>{{task.status}} · {{task.progress}}%</span><small>{{task.audio_status}} · attempt {{task.attempt}}</small></div></div>
   </aside>
  </div>
 </template>
</main>
</template>
<style scoped>
.studio{max-width:1220px;margin:0 auto;color:#26322c}.studio header{display:flex;justify-content:space-between;gap:24px;padding-bottom:18px;border-bottom:1px solid #d7e0da}.eyebrow{margin:0 0 6px;color:#39765a;font-size:10px;font-weight:800}.studio h1{margin:0;font-size:24px;letter-spacing:0}.studio header p:last-child{margin:6px 0 0;color:#6c786f;font-size:12px}.runtime{display:grid;grid-template-columns:auto 1fr;min-width:290px;padding:11px 13px;border:1px solid #c9ddd0;background:#f1f7f3;color:#335c42}.runtime svg{grid-row:1/3;margin-right:8px}.runtime span{font-size:11px;font-weight:800}.runtime small{font-size:9px}.runtime.bad{border-color:#e1beb7;background:#fff1ef;color:#84483d}.notice{padding:10px;background:#f3f6f4;font-size:11px}.err{background:#fff0ed;color:#8a4339}.toolbar{display:flex;gap:8px;margin-top:14px}.toolbar select{flex:1;height:36px;padding:0 10px;border:1px solid #d1dbd4;background:#fff}.toolbar button,.actions button,.downloads button{display:inline-flex;align-items:center;justify-content:center;gap:5px;min-height:34px;padding:0 10px;border:1px solid #cbd7cf;background:#fff;color:#35483c}.layout{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.8fr);gap:14px;margin-top:14px}.editor,aside{border:1px solid #d9e1dc;background:#fff;padding:14px}.section-head{display:flex;justify-content:space-between;gap:12px;padding-bottom:12px;border-bottom:1px solid #e4eae6}.section-head div{display:flex;flex-direction:column}.section-head small{color:#849087;font-size:9px}.section-head input{width:55%;padding:8px;border:1px solid #d6ded8}.editor article{display:grid;grid-template-columns:32px 1fr 25px;gap:10px;padding:13px 0;border-bottom:1px solid #edf0ee}.scene-no{display:flex;width:28px;height:28px;align-items:center;justify-content:center;background:#17342b;color:#fff;font-size:11px}.fields{display:grid;grid-template-columns:1fr 160px;gap:7px}.fields input,.fields textarea{padding:8px;border:1px solid #d6ded8;font:inherit;font-size:11px}.fields textarea{grid-column:1/3;min-height:58px;resize:vertical}.fields label{display:flex;align-items:center;gap:7px;font-size:9px;color:#728077}.fields label input{width:80px}.remove{height:25px;border:0;background:#f7eeec;color:#92534a}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.actions .primary{background:#17342b;color:#fff;border-color:#17342b}.spin{animation:spin 1s linear infinite}.truth{display:flex;gap:9px;padding:10px;background:#f1f6f3;color:#365847}.truth div{display:flex;flex-direction:column}.truth strong{font-size:11px}.truth small{margin-top:3px;font-size:9px;line-height:1.5}.preview video{width:100%;margin-top:12px;background:#101a16;aspect-ratio:16/9}.preview dl{display:grid;grid-template-columns:76px 1fr;gap:6px;margin:12px 0;font-size:10px}.preview dt{color:#7b887f}.hash{overflow-wrap:anywhere;font-family:monospace}.downloads{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.empty{display:flex;min-height:260px;flex-direction:column;align-items:center;justify-content:center;color:#7f8b83}.empty strong{margin-top:8px;font-size:12px}.empty span{font-size:9px}.history{margin-top:14px;border-top:1px solid #e1e7e3;padding-top:10px}.history>strong{font-size:10px}.history>div{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #edf0ee;font-size:9px}.history small{color:#7c8980}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:850px){.studio header{flex-direction:column}.runtime{min-width:0}.layout{grid-template-columns:1fr}.section-head{flex-direction:column}.section-head input{width:auto}}@media(max-width:430px){.toolbar{flex-wrap:wrap}.toolbar select{min-width:100%}.fields{grid-template-columns:1fr}.fields textarea{grid-column:auto}.editor,aside{padding:10px}.studio h1{font-size:20px}}
</style>
